/**
 * i18n/index.js
 * Drift's translation runtime. English text IS the key (gettext-style):
 *
 *   tr("Share code")
 *   tr("{{n}} min left", { n })
 *
 * so untranslated strings fall back to readable English for free, and the
 * call site still says what the user sees. Catalogs live in i18n/locales/<code>.json
 * ({ "<english>": "<translation>" }) and are generated by tools/i18n/; don't
 * hand-edit the English side of a key without rerunning the extractor, or the
 * translations stop matching.
 *
 * Language choice: the user's pick (Profile → Language) wins, else the device
 * language if Drift ships it, else English. Changing it re-mounts the app
 * root (App.js keys on the locale) so memoised screens re-render, and
 * module-level option lists use getters so they re-read tr() on access.
 */
import AsyncStorage from "@react-native-async-storage/async-storage";
import { useSyncExternalStore } from "react";
import { LANGUAGES, matchLanguage } from "./languages";
import { CATALOGS } from "./catalogs";
import { NativeModules } from "react-native";

const STORAGE_KEY = "drift_language"; // "" / missing = follow the device

let current = "en";
let dict = null;
let pinned = null; // the user's explicit choice, or null
const listeners = new Set();

function deviceLanguage() {
  try {
    const tag = Intl.DateTimeFormat().resolvedOptions().locale;
    return matchLanguage(tag) || "en";
  } catch {
    return "en";
  }
}

// Dates and numbers formatted with no explicit locale (toLocaleDateString(),
// toLocaleString(undefined, …)) should follow the app language, not the
// device's, or a user who picked Español sees "October 25" next to Spanish
// copy. Patch the defaults once rather than threading a locale through every
// call site.
let patched = false;
function patchIntlDefaults() {
  if (patched) return;
  patched = true;
  const wrap = (proto, name) => {
    const orig = proto[name];
    if (typeof orig !== "function") return;
    proto[name] = function (locales, options) {
      return orig.call(this, locales === undefined || locales === null || (Array.isArray(locales) && !locales.length) ? current : locales, options);
    };
  };
  wrap(Date.prototype, "toLocaleDateString");
  wrap(Date.prototype, "toLocaleTimeString");
  wrap(Date.prototype, "toLocaleString");
  wrap(Number.prototype, "toLocaleString");
}

function apply(code) {
  patchIntlDefaults();
  current = code;
  dict = code === "en" ? null : (CATALOGS[code]?.() || null);
  // Mirror into the App Group so the shield, DriftMonitor notifications and
  // widgets (which can't read JS state) speak the same language. Called on the
  // module directly rather than through screenTime.js to avoid an import cycle.
  try { NativeModules.ScreenTimeModule?.setLanguage?.(code).catch?.(() => {}); } catch {}
  listeners.forEach((l) => l());
}

/** Load the saved choice once at boot. Resolves fast; App.js waits on it. */
export async function initI18n() {
  let saved = null;
  try { saved = await AsyncStorage.getItem(STORAGE_KEY); } catch {}
  pinned = saved && LANGUAGES.some((l) => l.code === saved) ? saved : null;
  apply(pinned || deviceLanguage());
}

/** code = null → follow the device language. */
export async function setLanguage(code) {
  pinned = code && LANGUAGES.some((l) => l.code === code) ? code : null;
  try {
    if (pinned) await AsyncStorage.setItem(STORAGE_KEY, pinned);
    else await AsyncStorage.removeItem(STORAGE_KEY);
  } catch {}
  apply(pinned || deviceLanguage());
  // Module-level copy was evaluated in the old language; reload the bundle so
  // it re-runs. Without the native hook (Expo Go) App.js's keyed remount is
  // the fallback and a few constants stay in the old language until restart.
  try { await NativeModules.ScreenTimeModule?.reloadApp?.(); } catch {}
}

export function getLanguage() { return current; }
export function getPinnedLanguage() { return pinned; }
export function isRTL() { return !!LANGUAGES.find((l) => l.code === current)?.rtl; }

/** BCP-47 tag for Intl / toLocaleString. */
export function intlLocale() { return current; }

/** Re-render on language change. Returns the current code. */
export function useLanguage() {
  return useSyncExternalStore(
    (cb) => { listeners.add(cb); return () => listeners.delete(cb); },
    () => current,
  );
}

export function tr(key, params) {
  let s = (dict && dict[key]) || key;
  if (params) {
    s = s.replace(/\{\{(\w+)\}\}/g, (m, k) => (params[k] === undefined || params[k] === null ? "" : String(params[k])));
  }
  return s;
}

export { LANGUAGES };
